    long long n;
    cin >> n;
    vector<vector<long long>> g(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> g[i][j];
        }
    }

    long long mainSum = 0, anti = 0;
    for (int i = 0; i < n; i++) {
        mainSum += g[i][i];
        anti += g[i][n - 1 - i];
