code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[][] g = new long[(int) n][(int) n];
        for (int i = 0; i < g.length; i++) {
            for (int j = 0; j < g[i].length; j++) {
                g[i][j] = sc.nextLong();
            }
        }

        long main = 0, anti = 0;
        for (int i = 0; i < n; i++) {
            main += g[i][i];
            anti += g[i][(int) n - 1 - i];
        }
        System.out.println(main + " " + anti);
    }
}
